<template>
  <main class="content"><div class="title"><div><div class="eyebrow">平台运营 / 用户管理</div><h1>用户管理</h1><p>管理普通用户、主办方管理员和核销员账号的使用状态。</p></div></div>
    <section class="panel toolbar"><input v-model.trim="keyword" placeholder="搜索姓名、用户名、昵称、手机号或 ID" @keyup.enter="load" /><select v-model="roleCode" @change="load"><option value="">全部角色</option><option value="USER">普通用户</option><option value="ORGANIZER_ADMIN">主办方管理员</option><option value="VERIFIER">核销员</option><option value="PLATFORM_ADMIN">平台管理员</option></select><select v-model="enabledFilter" @change="load"><option value="">全部状态</option><option value="true">正常</option><option value="false">已停用</option></select><button type="button" @click="load">查询</button></section>
    <p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }} <button @click="load">重新加载</button></p>
    <section class="panel table-wrap"><div v-if="loading" class="state">用户加载中…</div><div v-else-if="!users.length" class="state">暂无用户</div><table v-else><thead><tr><th>用户</th><th>联系方式</th><th>角色</th><th>所属主办方</th><th>状态</th><th>注册时间</th><th class="user-operation-column">操作</th></tr></thead><tbody><tr v-for="item in users" :key="item.id"><td><StaffIdentity :account="identity(item)" :subtitle="item.username + ' · ID：' + item.id" /><small v-if="isStaff(item)&&(!item.name||!item.phone)">资料待补全</small></td><td>{{ item.phone || '未填写' }}</td><td>{{ roleLabel(item.roleCodes) }}</td><td><RouterLink v-for="org in item.organizers || []" :key="org.id" :to="'/management/platform/organizers/'+org.id">{{ org.name }}<br /></RouterLink><span v-if="!item.organizers?.length">—</span></td><td><span class="status" :class="item.enabled ? 'enabled' : 'disabled'">{{ item.enabled ? '正常' : '已停用' }}</span></td><td>{{ formatDate(item.createdAt) }}</td><td class="user-operation-cell"><div class="user-actions" :class="{'account-actions':manageable(item)}"><button type="button" class="action" @click="historyTarget=item">操作记录</button><template v-if="manageable(item)"><button type="button" class="action" :class="{danger:item.enabled}" :disabled="!!pending" @click="openAction(item,item.enabled ? 'disable' : 'enable')">{{ item.enabled ? '停用账号' : '启用账号' }}</button><button v-if="isStaff(item)" type="button" class="action" @click="profileTarget=item">编辑资料</button><details v-if="item.enabled" class="more-actions"><summary>更多操作</summary><button type="button" :disabled="!!pending" @click="openAction(item,'force')">强制下线</button></details></template><button v-else-if="String(item.id)===currentUserId&&isStaff(item)" class="action" @click="profileTarget=item">我的资料</button><span v-else class="protected-note">{{ String(item.id) === currentUserId ? '当前账号' : '暂不提供状态操作' }}</span></div></td></tr></tbody></table></section>
    <AccountOperationHistory v-if="historyTarget" :key="historyTarget.id" :target="historyTarget" @close="historyTarget=null" /><StaffProfileDialog v-if="profileTarget" :self="String(profileTarget.id)===currentUserId" :target="profileTarget" @close="profileTarget=null" @saved="profileSaved" /><Teleport to="body"><div v-if="pending" class="action-backdrop"><section class="action-dialog" role="dialog" aria-modal="true" aria-labelledby="account-action-title" aria-describedby="account-action-message"><h2 id="account-action-title">{{ actionTitle }}</h2><p class="target-account">{{ pending.item.name || pending.item.username }} · {{ pending.item.username }}</p><p id="account-action-message">{{ actionDescription }}</p><label class="reason-field">{{ pending.kind==='disable'?'停用原因（必填）':'操作备注（选填）' }}<textarea v-model="operationReason" name="operationReason" rows="3" maxlength="500" placeholder="请填写具体原因或备注（最多500字）"></textarea></label><p v-if="actionError" class="error" role="alert">{{ actionError }}</p><div class="dialog-buttons"><button type="button" :disabled="saving" @click="pending=null">取消</button><button type="button" class="confirm-action" :disabled="saving" @click="confirmAction">{{ saving ? '处理中…' : '确认' }}</button></div></section></div></Teleport>
  </main>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { platformUserApi } from '../../api/platformUser'
import { useAuthStore } from '../../stores/auth'
import { useRoute } from 'vue-router'
import StaffIdentity from '../../components/StaffIdentity.vue'
import StaffProfileDialog from '../../components/StaffProfileDialog.vue'
import AccountOperationHistory from '../../components/AccountOperationHistory.vue'
const historyTarget=ref(null),operationReason=ref('')
const profileTarget=ref(null)
const isStaff=item=>String(item.roleCodes||'').split(',').some(r=>['PLATFORM_ADMIN','ORGANIZER_ADMIN','VERIFIER'].includes(r))
const identity=item=>isStaff(item)?item:{...item,name:null,username:item.nickname||item.username}
async function profileSaved(){notice.value='工作人员资料已更新';await load()}
const auth=useAuthStore(),users=ref([]),keyword=ref(''),roleCode=ref(''),enabledFilter=ref(''),loading=ref(false),error=ref(''),notice=ref(''),pending=ref(null),saving=ref(false),actionError=ref('')
const route=useRoute()
watch(()=>route.query.keyword,value=>{keyword.value=String(value||'');load()},{immediate:true})
const currentUserId=computed(()=>{try{return String(JSON.parse(atob(auth.accessToken.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).sub || '')}catch{return ''}})
const roleLabel=value=>String(value||'').split(',').map(code=>({USER:'普通用户',ORGANIZER_ADMIN:'主办方管理员',VERIFIER:'核销员',PLATFORM_ADMIN:'平台管理员'}[code]||code)).join('、')||'未分配角色'
const formatDate=value=>value?value.slice(0,16).replace('T',' '):'—'
function manageable(item){const roles=String(item.roleCodes||'').split(',');return String(item.id)!==currentUserId.value && !roles.includes('PLATFORM_ADMIN') && roles.some(role=>['USER','ORGANIZER_ADMIN','VERIFIER'].includes(role))}
const actionTitle=computed(()=>({disable:'停用账号',enable:'启用账号',force:'强制下线'}[pending.value?.kind]||''))
const actionDescription=computed(()=>({disable:'停用后将结束该账号当前已登记的登录会话，并禁止重新登录。已有活动、订单和票券记录会保留。',enable:'启用后，该账号可以重新登录。之前失效的登录会话不会恢复。',force:'将结束该账号当前已登记的登录会话。账号仍可重新登录，此操作不会停用账号。'}[pending.value?.kind]||''))
async function load(){loading.value=true;error.value='';try{users.value=await platformUserApi.list({keyword:keyword.value||undefined,roleCode:roleCode.value||undefined,enabled:enabledFilter.value===''?undefined:enabledFilter.value==='true'})||[]}catch(e){error.value=e.message||'用户加载失败'}finally{loading.value=false}}
function openAction(item,kind){operationReason.value='';pending.value={item,kind};actionError.value='';notice.value=''}
async function confirmAction(){if(saving.value||!pending.value)return;if(pending.value.kind==='disable'&&!operationReason.value.trim()){actionError.value='请填写停用原因';return}saving.value=true;actionError.value='';const {item,kind}=pending.value;try{if(kind==='force')await platformUserApi.forceLogout(item.id,operationReason.value.trim());else await platformUserApi.updateEnabled(item.id,kind==='enable',operationReason.value.trim());notice.value=kind==='force'?'已结束该账号已登记的登录会话，账号仍可重新登录。':kind==='enable'?'账号已启用，请重新登录。':'账号已停用，已有登录会话已撤销。';pending.value=null;await load()}catch(e){actionError.value=e.message||'操作失败，请重试'}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>
.reason-field{display:block;font-size:13px;color:#52627e;margin-top:16px}.reason-field textarea{display:block;box-sizing:border-box;width:100%;margin-top:8px;padding:12px;border:1px solid #d5e0f4;border-radius:8px;font:inherit;resize:vertical}

.content{padding:34px;max-width:1500px}.title{margin-bottom:28px}.eyebrow{color:#6f7690;font-size:13px;margin-bottom:10px}h1{margin:0 0 8px;font-size:30px}.title p{margin:0;color:#6e7387}.panel{background:#fff;border:1px solid #e1e5ef;border-radius:10px;padding:22px;margin-bottom:20px}.toolbar{display:flex;gap:10px;flex-wrap:wrap}.toolbar input,.toolbar select{border:1px solid #dfe2ee;border-radius:7px;padding:9px 11px;background:#fafaff;min-width:150px}.toolbar input{min-width:240px}.toolbar button,.action,.error button{border:1px solid #cfd8f4;border-radius:7px;padding:8px 13px;background:#f5f7ff;color:#0d50dc}.action.danger{color:#bf4a50;border-color:#f0d5d7;background:#fff6f6}.content .table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:1180px}th,td{text-align:left;padding:15px;border-bottom:1px solid #ececf3}th{color:#61677a;font-size:13px}small{display:block;color:#858b9d;margin-top:5px}.status{display:inline-block;padding:5px 9px;border-radius:12px;font-size:12px}.enabled{background:#e0f8e9;color:#16834a}.disabled{background:#ffe7e7;color:#c53a43}.state,.protected-note{color:#737b90;font-size:12px}.error{color:#c53a43;font-size:13px;line-height:1.7}.notice{color:#16834a;background:#eaf8f0;border:1px solid #d2eddf;border-radius:8px;padding:12px 15px;font-size:13px}.user-operation-column{width:240px;min-width:240px}.user-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;align-items:start;width:206px}.table-wrap .user-actions .action,.table-wrap .user-actions .more-actions summary{display:inline-flex;align-items:center;justify-content:center;width:100%;height:34px;min-height:34px;padding:0 10px;line-height:1.4;white-space:nowrap;box-sizing:border-box;font-size:12px;border:1px solid #d6e0f4;border-radius:7px;background:#f4f7ff;color:#2161e8}.table-wrap .user-actions .action.danger{background:#fff6f6;border-color:#f0d5d7;color:#bf4a50}.table-wrap .user-actions .action:hover,.table-wrap .user-actions summary:hover{border-color:#9dbaf4;background:#edf3ff}.table-wrap .user-actions .action.danger:hover{background:#fff0f1;border-color:#e7a5ae}.user-actions .protected-note{grid-column:1/-1;line-height:1.6}.more-actions{position:relative;white-space:nowrap;font-size:12px;color:#737b90}.more-actions summary{cursor:pointer;list-style:none;gap:5px}.more-actions summary::-webkit-details-marker{display:none}.more-actions summary::after{content:"⌄";font-size:14px}.more-actions[open] summary::after{transform:rotate(180deg)}.user-actions .more-actions>button{width:100%;white-space:nowrap;min-height:34px;height:34px;padding:0 8px;font-size:12px}.more-actions button{margin-top:7px;border:1px solid #dce4f2;background:#fff;color:#2161e8;border-radius:7px;padding:8px 12px}.action-backdrop{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:24px;background:#14203a66;z-index:1000;backdrop-filter:blur(3px)}.action-dialog{width:min(440px,100%);padding:26px;background:#fff;border-radius:12px;box-shadow:0 20px 60px #14203a33;color:#16233b}.action-dialog h2{margin:0 0 12px;font-size:20px}.action-dialog p{font-size:13px;line-height:1.8;color:#74839b}.action-dialog .target-account{font-weight:600;color:#16233b;overflow-wrap:anywhere}.dialog-buttons{display:flex;justify-content:flex-end;gap:10px;margin-top:23px}.dialog-buttons button{min-width:82px;border:1px solid #dce4f2;background:#fff;border-radius:8px;height:40px;color:#74839b}.dialog-buttons .confirm-action{background:#2161e8;color:#fff;border-color:#2161e8}button:disabled{opacity:.5;cursor:default}@media(max-width:700px){.content{padding:20px 14px}.toolbar input{width:100%}}
</style>
